INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('chapter_30', '主线结局 · 十年之后', '一成不变', 'bg ch28_ochanomizu_steps', 0);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_karuizawa_fade', '轻井泽的淡季', '顾天鹏没有接受那份兼职。', 'bg ch17_pet_shop', 1);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_spring_no_line', '没有回信的春天', '照片被她收下了，联系方式却没有交换。', 'bg ch20_sakura_slope', 2);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_overclear_relationship', '过于明确的答案', '那个答案太快，也太明确。', 'bg ch23_tokyo_cafe_night', 3);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_unvisited_training', '未曾赴约的训练', '顾天鹏没有去御茶之水。', 'bg ch28_ochanomizu_steps', 4);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_summer_promise', '夏日的约定', '顾天鹏没有立刻追去车站，也没有把那封信当成故事的结尾。', 'bg ch10_old_karuizawa_street', 5);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('route_main_search', '追迹之旅', '顾天鹏没有把退房手续立刻办完。', 'bg ch10_inn_evening_room', 6);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('route_side_memory', '记忆之旅', '顾天鹏最后还是没有去车站询问。', 'bg ch10_inn_evening_room', 7);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_leaf_bookmark', '落叶书签', '那天之后，他们没有立刻把喜欢的理由说清楚。', 'bg ch9_roadside_steps', 8);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_missed_companion', '错过的旅伴', '夜色降下来以后，两个人之间重新变得安静。', 'bg train_table_night', 9);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_empty_encouragement', '空洞的鼓励', '黄昏把雪地染成温柔的金色。', 'bg ch5_summit_sunset', 10);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_light_answer', '轻易的答案', '掌声渐渐远去，白鸽也飞过屋檐。', 'bg ch10_white_church_wedding', 11);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_too_close', '太近的距离', '顾天鹏靠近得太快。', 'bg ch13_miharashidai_sunset', 12);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_white_church', '白色教堂', '那天他们没有继续站在教堂前看别人的婚礼。', 'bg ch10_white_church_wedding', 13);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_silver_chain', '银链', '离开饰品店时，星野爱没有买下那对手链。', 'bg ch10_old_karuizawa_street', 14);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_sunflower_between', '向日葵之间', '向日葵被放在两个人中间。', 'bg ch13_miharashidai_sunset', 15);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_bench_dawn', '长椅上的黎明', '那一晚，他们真的坐了很久。', 'bg ch14_roadside_bench_night', 16);
INSERT INTO sekai_GaLaGame_lies_endings (ending_key, title, description, bg_image, sort_no) VALUES ('ending_quiet_parting', '安静的告别', '顾天鹏醒来时，窗外的竹林被晨雾压得很低。', 'cg ch15_empty_room_letter', 17);
